export const AXES=[{key:'physique',label:'Physique'},{key:'iq',label:'IQ · reasoning'},{key:'eq',label:'EQ · connection'},{key:'craft',label:'Creativity'},{key:'drive',label:'Drive'}];
export const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
export function rand(seed,age,domain){let h=2166136261;for(const c of `${seed}/${age}/${domain}`){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}h+=h<<13;h^=h>>>7;h+=h<<3;h^=h>>>17;h+=h<<5;return(h>>>0)/4294967296;}
export const balanced=()=>Object.fromEntries(AXES.map(a=>[a.key,2]));
export const validPoints=p=>!!p&&Object.keys(p).length===5&&AXES.every(a=>Number.isInteger(p[a.key])&&p[a.key]>=0&&p[a.key]<=10)&&Object.values(p).reduce((a,b)=>a+b,0)===10;
export function transfer(p,key,delta){if(!validPoints(p)||!AXES.some(a=>a.key===key)||![1,-1].includes(delta))return p;const other=AXES.map(a=>a.key).filter(k=>k!==key).sort((a,b)=>p[b]-p[a])[0];if(delta>0&&p[other]===0||delta<0&&p[key]===0)return p;return {...p,[key]:p[key]+delta,[other]:p[other]-delta};}
export const defaultProfile=()=>({drink:'no',smoke:'no',religion:'explore',intimacy:'unsure',aim:'balance'});
export function newLife(seed=43127){const birth=rand(seed,0,'household');return {version:2,seed,stage:'birth',age:0,attributes:balanced(),effort:balanced(),profile:defaultProfile(),birth:{place:birth<.5?'Nakhon Sawan':'Samut Prakan',home:birth<.5?'a farming household':'a market-stall household',cash:birth<.5?18000:42000,sensitivity:rand(seed,0,'sensitivity')>.5?'Sensitive to pressure':'Steady under pressure',body:rand(seed,0,'body')>.5?'Strong physical starting condition':'Ordinary physical starting condition'},cash:birth<.5?18000:42000,health:rand(seed,0,'body')>.5?94:88,wellbeing:rand(seed,0,'sensitivity')>.5?62:68,skills:{physique:0,iq:0,eq:0,craft:0,drive:0},history:[],profiles:[],original:null,death:null,previous:null};}
export function begin(s){if(s.stage!=='birth'||!validPoints(s.attributes))return s;const start={age:0,health:s.health,wellbeing:s.wellbeing,cash:s.cash,event:'Born into '+s.birth.home,effort:{...s.attributes},profile:defaultProfile()};return {...s,age:10,stage:'review',original:{...s.attributes},effort:{...s.attributes},history:[start,{...start,age:10,event:'Childhood: family, school and the world you inherited.'}]};}
export const goals={balance:'A life with room to breathe',sport:'Become an athlete',art:'Make a life through art',security:'Build financial security',connection:'Love and belong'};
export function sanitiseProfile(p,age){const q={...defaultProfile()};for(const [key,allowed]of Object.entries({drink:['no','social'],smoke:['no','yes'],religion:['explore','practice','none'],intimacy:['unsure','together','separate'],aim:Object.keys(goals)}))if(allowed.includes(p?.[key]))q[key]=p[key];if(age<20){q.drink='no';q.smoke='no';q.intimacy='unsure';}return q;}
export function live(s){if(s.stage!=='review'||!validPoints(s.effort)||s.age>=80)return s;const from=s.age,age=from+5,p=sanitiseProfile(s.profile,from),e=s.effort;const adult=from>=20,retired=from>=60;const shock=rand(s.seed,age,'event');let event=age===20?'Leaving school changes your circle.':age===60?'Work slows. Your time becomes your own again.':'An ordinary five years. Small habits accumulate.';let setback=0,healthShock=0;
if(age===30){setback=18000;event='Floodwater damages the family home. Repairs take money and time.';}else if(age===55){event='Your father dies. The family has to find a different rhythm.';}else if(age===70){event='Your mother dies. Familiar places carry different memories.';}else if(adult&&shock<.15){setback=12000;event='A work interruption reduces the household buffer.';}else if(adult&&shock>.84){setback=-9000;event='An unexpected commission or extra work brings a little breathing room.';}
if(age>=40&&rand(s.seed,age,'illness')<.12){healthShock=12;event+=' A health setback interrupts your plans.';}
const earnings=adult?(retired?7000:12000+e.drive*2000+e.iq*1100+s.attributes.iq*500+e.craft*1000+e.physique*900):0;
const spending=adult?(retired?11000:14000):0;const habits=adult?((p.smoke==='yes'?4000:0)+(p.drink==='social'?2500:0)):0;
const cash=Math.round(s.cash+earnings-spending-habits-setback);const aging=from<30?1:from<50?4:from<65?7:10;const health=clamp(s.health-aging+e.physique*.5+s.attributes.physique*.15-(adult&&p.smoke==='yes'?6:0)-(adult&&p.drink==='social'?1.5:0)-healthShock);
const match={balance:Math.min(...Object.values(e))*.7,sport:e.physique*.6,art:e.craft*.6,security:e.drive*.4+e.iq*.2,connection:e.eq*.6}[p.aim];const social=adult&&p.drink==='social'?(e.eq>0?1:-1):0;const wellbeing=clamp(s.wellbeing+match+e.eq*.35+s.attributes.eq*.1+social-3-(cash<0?(s.birth.sensitivity==='Sensitive to pressure'?6:4):0)-(healthShock?4:0));
const hazard=age<25?.003:age<45?.009:age<60?.025:age<75?.07:.15;const death=rand(s.seed,age,'mortality')<hazard+(health<30?.15:0)?{age,cause:health<30?'A serious health event ended this life.':'An unexpected illness or accident ended this life.'}:null;
const skills=Object.fromEntries(AXES.map(a=>[a.key,s.skills[a.key]+e[a.key]]));const row={age,from,health,wellbeing,cash,event,effort:{...e},profile:{...p},earnings,spending:spending+habits,setback};return {...s,age,cash,health,wellbeing,skills,profile:p,profiles:[...s.profiles,{age:from,effort:{...e},profile:{...p}}],history:[...s.history,row],death,stage:death||age===80?'recap':'review'};}
export function replay(s){return {...newLife(s.seed),previous:{age:s.age,cash:s.cash,health:s.health,wellbeing:s.wellbeing,history:s.history,death:s.death}};}
export function validate(s){
 const profile=p=>p&&Object.entries(sanitiseProfile(p,80)).every(([k,v])=>p[k]===v);
 const row=r=>r&&Number.isInteger(r.age)&&r.age>=0&&r.age<=80&&['cash','health','wellbeing'].every(k=>Number.isFinite(r[k]))&&validPoints(r.effort)&&profile(r.profile)&&typeof r.event==='string';
 const death=d=>d===null||d&&Number.isInteger(d.age)&&typeof d.cause==='string';
 return s?.version===2&&(s.progressAge===undefined||Number.isFinite(s.progressAge)&&s.progressAge>=0&&s.progressAge<=80)&&Number.isInteger(s.seed)&&['birth','review','recap'].includes(s.stage)&&Number.isInteger(s.age)&&s.age>=0&&s.age<=80&&validPoints(s.attributes)&&validPoints(s.effort)&&profile(s.profile)&&['cash','health','wellbeing'].every(k=>Number.isFinite(s[k]))&&Array.isArray(s.history)&&s.history.length<=16&&s.history.every(row)&&Array.isArray(s.profiles)&&s.profiles.every(p=>p&&Number.isInteger(p.age)&&validPoints(p.effort)&&profile(p.profile))&&s.birth&&['place','home','sensitivity','body'].every(k=>typeof s.birth[k]==='string')&&AXES.every(a=>Number.isFinite(s.skills?.[a.key]))&&(s.original===null||validPoints(s.original))&&death(s.death)&&(s.previous===null||s.previous&&Number.isInteger(s.previous.age)&&['cash','health','wellbeing'].every(k=>Number.isFinite(s.previous[k]))&&Array.isArray(s.previous.history)&&s.previous.history.every(row)&&death(s.previous.death));
}
